/* HEXA BATTLEGROUNDS setup — PART 2 OF 20. Run parts in order. Safe to re-run. */ create or replace function _nearest_safe(p_from text, p_stage int) returns text language plpgsql stable as $$ declare visited text[]; frontier text[]; nxt text[]; v_hit text; i int; begin if p_from is null then p_from := 'hx_lobby'; end if; visited := array[p_from]; frontier := array[p_from]; for i in 1..20 loop select l.id into v_hit from locations l where l.id = any(frontier) and l.collapse_stage > p_stage and l.enabled and l.kind <> 'start' order by l.collapse_stage desc, l.id limit 1; if v_hit is not null then return v_hit; end if; select coalesce(array_agg(distinct n), '{}') into nxt from ( select case when e.a = any(frontier) then e.b else e.a end as n from edges e where e.a = any(frontier) or e.b = any(frontier) ) s where not (n = any(visited)); if array_length(nxt, 1) is null then exit; end if; visited := visited || nxt; frontier := nxt; end loop; return 'tr14'; end $$; create or replace function _pick_template(p_team uuid, p_kind text, p_tags text[]) returns text language plpgsql stable as $$ declare t teams; v_seed int; v text; begin select * into t from teams where id = p_team; select mission_seed into v_seed from events where id = t.event_id; select mt.id into v from mission_templates mt where mt.kind = p_kind and mt.status = 'published' and not exists (select 1 from mission_instances mi where mi.team_id = p_team and mi.template_id = mt.id) order by (mt.tags && coalesce(p_tags, '{}')) desc, md5(v_seed::text || p_team::text || mt.id || t.mission_counter::text) limit 1; if v is null then select mt.id into v from mission_templates mt where mt.kind = p_kind and mt.status = 'published' order by (mt.tags && coalesce(p_tags, '{}')) desc, md5(v_seed::text || p_team::text || mt.id || t.mission_counter::text) limit 1; end if; return v; end $$; create or replace function _codeword(p_seed text) returns text language sql immutable as $$ select (array['FALCON','TIGER','COBRA','RAVEN','VIPER','ORCA','LYNX','MANTIS','HAWK','BISON','JAGUAR', 'PANTHER','CONDOR','IBIS','OTTER','PUMA','KESTREL','WOLF','GECKO','MARLIN']) [1 + abs(hashtext(p_seed)) % 20] $$; create or replace function _start_instance( p_team uuid, p_template text, p_location text default null, p_battle uuid default null, p_airdrop uuid default null, p_sync uuid default null, p_deadline timestamptz default null, p_partner uuid default null ) returns uuid language plpgsql as $$ declare t teams; mt mission_templates; v_id uuid; v_partner uuid; v_key text; v_seed int; begin select * into t from teams where id = p_team for update; select * into mt from mission_templates where id = p_template; if mt.id is null then raise exception 'NO_TEMPLATE'; end if; select mission_seed into v_seed from events where id = t.event_id; if mt.relay then v_partner := p_partner; if v_partner is null then select x.id into v_partner from teams x where x.arena_id = t.arena_id and x.ready and x.id <> t.id order by md5(v_seed::text || t.id::text || x.id::text || t.mission_counter::text) limit 1; end if; v_key := _codeword(v_seed::text || t.id::text || t.mission_counter::text); end if; insert into mission_instances(arena_id, team_id, template_id, template_version, kind, location_id, battle_id, airdrop_id, sync_round_id, attempts_left, deadline, partner_team_id, relay_key, fallback_at) values (t.arena_id, t.id, mt.id, mt.version, mt.kind, coalesce(p_location, t.location_id), p_battle, p_airdrop, p_sync, mt.attempts, coalesce(p_deadline, now() + _secs(mt.time_limit)), v_partner, v_key, case when mt.relay and v_partner is not null then now() + _secs(_cfg(t.event_id, 'intel_fallback')) when mt.relay then now() end) returning id into v_id; update teams set mission_counter = mission_counter + 1, visit_missions = visit_missions + case when mt.kind in ('mission', 'relay') then 1 else 0 end where id = t.id; perform _ping_team(t.id, 'mission'); if v_partner is not null then perform _ping_team(v_partner, 'intel'); end if; return v_id; end $$; create or replace function _start_location_mission(p_team uuid) returns uuid language plpgsql as $$ declare t teams; l locations; v_kind text := 'mission'; v_tpl text; v_seed int; v_others int; begin select * into t from teams where id = p_team; select * into l from locations where id = t.location_id; select mission_seed into v_seed from events where id = t.event_id; select count(*) into v_others from teams where arena_id = t.arena_id and ready and id <> t.id; if v_others > 0 and ( l.tags && array['social', 'public', 'market'] or abs(hashtext(v_seed::text || t.id::text || t.mission_counter::text)) % 100 < _cfg(t.event_id, 'relay_chance')) then v_kind := 'relay'; end if; v_tpl := _pick_template(p_team, v_kind, l.tags || array['any']); if v_tpl is null then v_tpl := _pick_template(p_team, 'mission', l.tags || array['any']); end if; if v_tpl is null then return null; end if; return _start_instance(p_team, v_tpl, t.location_id); end $$; create or replace function _enter_recovery(p_team uuid) returns void language plpgsql as $$ declare t teams; v_tpl text; begin select * into t from teams where id = p_team for update; if t.state = 'recovery' then return; end if; update mission_instances set status = 'cancelled' where team_id = p_team and status = 'active' and kind <> 'battle' and sync_round_id is null; update teams set state = 'recovery', travel_to = null, travel_arrive_at = null, recovery_deadline = now() + _secs(_cfg(t.event_id, 'recovery_seconds')) where id = p_team; perform _apply(p_team, 'recovery_penalty', -_cfg(t.event_id, 'pen_recovery'), 0, 0, 0, null, 'HP reached zero'); if not exists (select 1 from mission_instances where team_id = p_team and status = 'active' and kind <> 'battle') then v_tpl := _pick_template(p_team, 'recovery', array['any']); if v_tpl is not null then perform _start_instance(p_team, v_tpl, null, null, null, null, now() + _secs(_cfg(t.event_id, 'recovery_seconds'))); end if; end if; perform _feed(t.arena_id, 'recovery.started', jsonb_build_object('team', t.number)); perform _ping_team(p_team, 'recovery'); end $$; create or replace function _respawn(p_team uuid, p_reason text) returns void language plpgsql as $$ declare t teams; begin select * into t from teams where id = p_team for update; if t.state <> 'recovery' then return; end if; update mission_instances set status = case when status = 'active' then 'expired' else status end where team_id = p_team and kind = 'recovery' and status = 'active'; update teams set state = 'idle', recovery_deadline = null, hp = _cfg(t.event_id, 'hp_respawn'), protected_until = now() + _secs(_cfg(t.event_id, 'protect_seconds')) where id = p_team; perform _feed(t.arena_id, 'recovery.completed', jsonb_build_object('team', t.number, 'how', p_reason)); perform _ping_team(p_team, 'recovery'); end $$; create or replace function _resolve_battle(p_battle uuid, p_winner uuid) returns void language plpgsql as $$ declare b battles; v_loser uuid; ta teams; tb teams; v_dealt int := 0; v_ev uuid; begin select * into b from battles where id = p_battle for update; if b.status <> 'active' then return; end if; v_ev := _event_of_arena(b.arena_id); update battles set status = 'resolved', winner_id = p_winner, resolved_at = now() where id = b.id; if p_winner is not null then v_loser := case when p_winner = b.attacker_id then b.defender_id else b.attacker_id end; update mission_instances set status = 'solved', solved_at = now() where battle_id = b.id and team_id = p_winner and status = 'active'; update mission_instances set status = 'failed' where battle_id = b.id and team_id = v_loser and status = 'active'; perform _apply(p_winner, 'battle_win', _cfg(v_ev, 'pts_battle'), 20, 0, 0, b.id::text, 'Battle victory'); update teams set battle_wins = battle_wins + 1 where id = p_winner; update mission_instances set points_awarded = _cfg(v_ev, 'pts_battle') where battle_id = b.id and team_id = p_winner; v_dealt := _damage(v_loser, b.damage, 'battle_damage', b.id::text, 'Lost a battle'); else update mission_instances set status = 'expired' where battle_id = b.id and status = 'active'; end if; update teams set attack_cooldown_until = now() + _secs(_cfg(v_ev, 'attack_cooldown')) where id = b.attacker_id; update teams set protected_until = now() + _secs(_cfg(v_ev, 'protect_seconds')) where id in (b.attacker_id, b.defender_id); select * into ta from teams where id = b.attacker_id; select * into tb from teams where id = b.defender_id; perform _feed(b.arena_id, 'battle.resolved', jsonb_build_object( 'attacker', ta.number, 'defender', tb.number, 'weapon', b.weapon, 'winner', (select number from teams where id = p_winner), 'damage', v_dealt)); perform _ping_team(b.attacker_id, 'battle'); perform _ping_team(b.defender_id, 'battle'); end $$; create or replace function _standings(p_arena uuid) returns jsonb language sql stable as $$ with s as ( select t.id, t.number, t.name, t.points, t.final_points, t.missions_completed, t.battle_wins, t.arena_id, (select number from arenas a where a.id = t.arena_id) as arena_number, rank() over (order by t.points desc, t.final_points desc, t.missions_completed desc, t.battle_wins desc) as rnk from teams t where t.ready and t.arena_id = p_arena ) select coalesce(jsonb_agg(jsonb_build_object( 'rank', rnk, 'team_id', id, 'number', number, 'name', name, 'points', points, 'final_points', final_points, 'missions', missions_completed, 'battles', battle_wins, 'arena', arena_number, 'tie', (select count(*) from s s2 where s2.rnk = s.rnk) > 1 ) order by rnk, number), '[]'::jsonb) from s $$; create or replace function _event_standings(p_event uuid) returns jsonb language sql stable as $$ with s as ( select t.id, t.number, t.name, t.points, t.final_points, t.missions_completed, t.battle_wins, (select number from arenas a where a.id = t.arena_id) as arena_number, rank() over (order by t.points desc, t.final_points desc, t.missions_completed desc, t.battle_wins desc) as rnk from teams t where t.ready and t.event_id = p_event ) select coalesce(jsonb_agg(jsonb_build_object( 'rank', rnk, 'team_id', id, 'number', number, 'name', name, 'points', points, 'final_points', final_points, 'missions', missions_completed, 'battles', battle_wins, 'arena', arena_number, 'tie', (select count(*) from s s2 where s2.rnk = s.rnk) > 1 ) order by rnk, number), '[]'::jsonb) from s $$; create or replace function _apply_zone(p_arena uuid) returns void language plpgsql as $$ declare a arenas; t record; v_safe text; begin select * into a from arenas where id = p_arena; for t in select tm.* from teams tm join locations l on l.id = tm.location_id where tm.arena_id = p_arena and tm.ready and l.collapse_stage <= a.zone_stage and tm.state <> 'traveling' for update of tm loop v_safe := _nearest_safe(t.location_id, a.zone_stage); if t.state <> 'recovery' and t.zone_penalty_stage < a.zone_stage then perform _damage(t.id, _cfg(a.event_id, 'dmg_zone'), 'zone_damage', 'zone-' || a.zone_stage, 'Caught outside the safe zone'); end if; update teams set location_id = v_safe, zone_penalty_stage = greatest(zone_penalty_stage, a.zone_stage), visit_missions = 0 where id = t.id; perform _feed(p_arena, 'zone.relocated', jsonb_build_object('team', t.number, 'to', v_safe)); perform _ping_team(t.id, 'zone'); end loop; for t in select tm.* from teams tm join locations l on l.id = tm.travel_to where tm.arena_id = p_arena and tm.state = 'traveling' and l.collapse_stage <= a.zone_stage for update of tm loop update teams set travel_to = _nearest_safe(t.travel_to, a.zone_stage) where id = t.id; perform _ping_team(t.id, 'zone'); end loop; end $$; create or replace function _zone_advance(p_arena uuid) returns void language plpgsql as $$ declare a arenas; begin update arenas set zone_stage = least(5, zone_stage + 1), zone_next_at = null where id = p_arena returning * into a; perform _feed(p_arena, 'zone.collapsed', jsonb_build_object('stage', a.zone_stage)); perform _apply_zone(p_arena); end $$; create or replace function _spawn_airdrop(p_arena uuid, p_location text, p_tier text) returns uuid language plpgsql as $$ declare a arenas; v_loc text := p_location; v_tpl text; v_id uuid; v_tier text := coalesce(p_tier, 'common'); begin select * into a from arenas where id = p_arena; if v_loc is null then select id into v_loc from locations where enabled and collapse_stage > a.zone_stage + 1 and kind <> 'start' and id <> 'tr14' order by (tags && array['airdrop', 'public']) desc, random() limit 1; if v_loc is null then v_loc := 'tr14'; end if; end if; select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' and id not in (select template_id from airdrops where arena_id = p_arena) order by random() limit 1; if v_tpl is null then select id into v_tpl from mission_templates where kind = 'airdrop' and status = 'published' order by random() limit 1; end if; if v_tpl is null then raise exception 'NO_AIRDROP_TEMPLATE'; end if; insert into airdrops(arena_id, location_id, tier, template_id, expires_at) values (p_arena, v_loc, v_tier, v_tpl, now() + _secs(_cfg(a.event_id, 'airdrop_window'))) returning id into v_id; update arenas set last_airdrop_at = now() where id = p_arena; perform _feed(p_arena, 'airdrop.spawned', jsonb_build_object('location', v_loc, 'tier', v_tier)); return v_id; end $$; create or replace function _finalize_roles(p_arena uuid) returns void language plpgsql as $$ declare t record; p record; v_missing text[]; begin for t in select * from teams where arena_id = p_arena and ready loop select array_agg(r) into v_missing from unnest(array['captain', 'scout', 'decoder', 'intel']) r where not exists (select 1 from players where team_id = t.id and active and role = r); if v_missing is null then continue; end if; for p in select * from players where team_id = t.id and active and role is null order by joined_at loop exit when array_length(v_missing, 1) is null; update players set role = v_missing[1] where id = p.id; v_missing := v_missing[2:]; end loop; end loop; end $$;
